window.RP_SESSION={"id":"S-b1ed03f66313","messages":[{"id":"RP-II-0115778","time":"2026-07-11T16:45:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"바쁘게 움직이는 메리 록! \n몸이 거대한데도 빠르게 움직인다.\n맥주잔 6잔을 한번에 옮기려고 한다...","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115779","time":"2026-07-11T16:45:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115780","time":"2026-07-11T16:45:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'메리 록'의 민첩 판정 :\n[3] + [-1] = [2]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0115781","time":"2026-07-11T16:45:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"우당탕당탕ㄷ그기ㅡ탕!\n맥주잔을 넘어트렸다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115782","time":"2026-07-11T16:46:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"으악, 무슨 소리지? 드디어 지하에서 지옥염왕이 올라온 건가?!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115783","time":"2026-07-11T16:46:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네이놈, 어둠대왕의 힘을 맛봐랏!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115784","time":"2026-07-11T16:46:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델다닥.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115785","time":"2026-07-11T16:47:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 델타이이인... \"\n\n만신창이.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115786","time":"2026-07-11T16:47:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"바닥에서 뭐하세요? 혹시 케닌 놀이?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115787","time":"2026-07-11T16:47:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 보면 몰라아? 넘어진거잖아아. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115788","time":"2026-07-11T16:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 왜 넘어지셨대요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115789","time":"2026-07-11T16:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"바닥이랑 뽀뽀하셨어요?\"\n\n델타인이 메리 록의 뒷덜미를 붙잡고 들어올립니다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115790","time":"2026-07-11T16:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-c93f55c91873"]},{"id":"RP-II-0115791","time":"2026-07-11T16:48:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 힘 판정 :\n[7] + [0] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0115792","time":"2026-07-11T16:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어우, 무거워.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115793","time":"2026-07-11T16:49:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어휴, 옷이 다 젖었네요. 가서 좀 씻고 오세요. 맥주 냄새 나요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115794","time":"2026-07-11T16:49:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 여기 맥주 언제나와 맥주-! \"","characters":[]},{"id":"RP-II-0115795","time":"2026-07-11T16:51:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"바닥이 맥주를 다 마셔버렸네요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115796","time":"2026-07-11T16:51:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"좀만 기다리세요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115797","time":"2026-07-11T16:52:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"손님 한 명이 메리의 엉덩이를 툭! 때리며 킬킬 웃었습니다.\n\n\" 하하, 자네 맥주는 이 아가씨가 다 부어버리던데? \"","characters":[]},{"id":"RP-II-0115798","time":"2026-07-11T16:55:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" ! \"\n\n제 엉덩이 손으로 숨기더니 손님 쪽 째려본다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115799","time":"2026-07-11T16:57:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 저기요오, 이게 뭐하시는거예요오. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115800","time":"2026-07-11T17:02:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 록-!! 손님들이 기다리잖나-!! \"","characters":[]},{"id":"RP-II-0115801","time":"2026-07-11T17:02:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 맥주 여섯잔-! 말린 버섯과 송어구이!! 언제까지 서 있을거야-! \"","characters":[]},{"id":"RP-II-0115802","time":"2026-07-11T17:02:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 돈 벌어야지 돈! 시간이 곧 금이라구!! \"","characters":[]},{"id":"RP-II-0115803","time":"2026-07-11T17:03:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 으, 으아앗, 네에, 갑니다아! \"\n\n축축해진 옷을 이끌고 다시 주방 쪽으로 향합니다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115804","time":"2026-07-11T17:04:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 그 말 좋은데요? 시간은 곧 금이다?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115805","time":"2026-07-11T17:06:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인도 메리 록을 도와주기 위해 델다닥.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115806","time":"2026-07-11T17:09:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 델타이인, 고마워어... \" \n\n침착하게 음식들을 서빙합니다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115807","time":"2026-07-11T17:09:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭘요, 친구잖아요?\"\n\n델타인은 맥주잔들을 두 손으로만 잡는 대신, 또 촉수를 꺼내고…","characters":["P-c93f55c91873"]},{"id":"RP-II-0115808","time":"2026-07-11T17:27:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 친구! 나 정말 감동이야아. 바쁘지만 않았다면 꽈악 안았을텐데에! \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115809","time":"2026-07-11T17:28:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 안는 거 좋죠. 전에 의뢰 가서 데이지랑도 포옹해봤걸랑요. 아, 하지만 맥주는 닦고 안아주세요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115810","time":"2026-07-11T17:30:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 오, 맞다아. 맥주우. 갈아입을 옷이~ 하나 있었던 것 같아아! \"\n\n서빙 다 하고 나서는 제 옷 바라봅니다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115811","time":"2026-07-11T17:33:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"옷이 여분이 있으시다고?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115812","time":"2026-07-11T17:33:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그래도 돈이 좀 있으셨구나….\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115813","time":"2026-07-11T17:34:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"전 두벌 신사거든요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115814","time":"2026-07-11T17:34:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 더러워어. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115815","time":"2026-07-11T17:35:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 뭐어, 우리 엄마가 유우~명한 해적이었으니까아. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115816","time":"2026-07-11T17:35:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엥? 진짜요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115817","time":"2026-07-11T17:35:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어머니가 계셨다고요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115818","time":"2026-07-11T17:36:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"전 둘 다 죽어서 없거든요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115819","time":"2026-07-11T17:36:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"길드 사람들은 루체 빼고 다 고아인 줄 알았는데….\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115820","time":"2026-07-11T17:36:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"타박타박타박, 가볍고 딱딱한 발걸음 소리가 들려왔습니다.\n\n\"오, 저도요.\"\n갑자가 불청객이 난입했습니다.\n눈치가 조금 부족해보이는 해골이네요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115821","time":"2026-07-11T17:36:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 엄마 아빠 다 있었거드은? 지금 아빠는 없구, 엄마는 누워있긴 하지마안. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115822","time":"2026-07-11T17:37:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 꺄악! \"\n\n... 잠깐만!\n\n\" 해골이다아~ \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115823","time":"2026-07-11T17:37:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 내 하수인인가?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115824","time":"2026-07-11T17:37:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이봐, 가서 걸레랑 밀대 좀 가져와.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115825","time":"2026-07-11T17:37:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델뻔뻔의 촉수들이 맥주 여섯 잔을 세 테이블에 동시에 내려놓습니다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115826","time":"2026-07-11T17:38:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"으엥~? 굳이 따지자면 전 손님인데요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115827","time":"2026-07-11T17:38:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭐야, 그냥 언데드잖아.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115828","time":"2026-07-11T17:38:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"크게 실망하여 돌아섭니다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115829","time":"2026-07-11T17:39:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"델타인의 촉수를 보고 깜짝 놀라며 덜그럭거립니다.\n\"오우, 아마이징! 그 촉수들은 뭐에요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115830","time":"2026-07-11T17:40:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"보면 몰라요? 이계에서 불러낸 불경한 촉수들이잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115831","time":"2026-07-11T17:41:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"어디 물가에서 잡아온 쭈꾸미 다리인 것마냥 편하게 얘기하시는군요..\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115832","time":"2026-07-11T17:42:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"쭈… 뭐요? 그게 뭔데요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115833","time":"2026-07-11T17:42:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"...아, 대충.. 조그마한 문어같은 거 있어요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115834","time":"2026-07-11T17:44:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 크라켄 같은 건가?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115835","time":"2026-07-11T17:45:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그정도로 대단한 건 아니예요. 너무 쫄지 마세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115836","time":"2026-07-11T17:45:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"하지만 촉수 대신 절 보고 경배하는 건 허락해드리죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115837","time":"2026-07-11T17:46:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"제 이름은 델타인 페트로비치 바그로프. 어둠대왕이 될 사람이니까요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115838","time":"2026-07-11T17:47:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"오우, 그으렇군요..\"\n촉수를 쳐다보며 두개골을 긁적이다,\n\"그렇다면 제 이름은 아마이 조. 최고로 아마이징한 예술가이자 전투원이 될 해골입니다!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115839","time":"2026-07-11T17:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엄… 상당히 허접한 이름이네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115840","time":"2026-07-11T17:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"게다가 엄청 짧고.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115841","time":"2026-07-11T17:48:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"느엑?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115842","time":"2026-07-11T17:48:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"그쪽은 너무 복잡하고 긴데요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115843","time":"2026-07-11T17:49:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그러니까 심오하고 깊은 맛이 있는 거죠!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115844","time":"2026-07-11T17:49:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"델타인 페투로팟슈.. 뭐요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115845","time":"2026-07-11T17:49:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아무튼 와따마 씨, 주문 안하실 거면 이만 가주실래요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115846","time":"2026-07-11T17:49:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어차피 언데드라 아무것도 안 드시잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115847","time":"2026-07-11T17:51:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"쩝.\"\n뭐라 말하려 입을 벌렸다, 닫았다를 두어번 반복합니다.\n\"..뭐라 할 말이 없군요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115848","time":"2026-07-11T17:51:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 여기 고기파이 하나 더 주쇼! \"","characters":[]},{"id":"RP-II-0115849","time":"2026-07-11T17:51:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 와따마 씨. 주문이 들어왔어요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115850","time":"2026-07-11T17:52:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"얼른 가보세요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115851","time":"2026-07-11T17:52:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"...네? 제가요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115852","time":"2026-07-11T17:52:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"할 일도 없으신 것 같은데 조금이라도 생산적인 일을 해보셔야죠!\"\n\n델타인이 아마이 조를 손님에게 보냅니다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115853","time":"2026-07-11T17:52:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"잠시 어리둥절해하다가, 그냥 받아들이고 손님에게로 향합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115854","time":"2026-07-11T17:52:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 신입 아니세요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115855","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"그, 그쵸?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115856","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c93f55c91873"]},{"id":"RP-II-0115857","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"야, 내가 네 선배야.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115858","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 아 뭘 그렇게 멀뚱멀뚱 서있어!? 고기 파이 하나 더 달라니까! \"\n\n\" 여기 맥주 두 잔 더 주쇼-! \"\n\n\" 사장님 계신가요? \"\n\n\" 여기 맥주 한 잔-!","characters":[]},{"id":"RP-II-0115859","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"선배님 말씀대로 햇!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115860","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"....\"\n아마이 조는 여기로 온 걸 아마이징하게 후회하고 있습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115861","time":"2026-07-11T17:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"맥주 두 잔 가요! 사장님은 없어요! 한스 씨가 어디 가셨걸랑요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115862","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭐해요, 얼른 고기파이 주방에 말해서 갖다드리세요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115863","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"이, 이렇게 된 이상 오히려 엄청 잘해버려서 놀라게 해주마..\"\n이상하게 승부욕이 붙은 아마이 조는 헐레벌떡 움직이기 시작합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115864","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"아마이, 민첩!","characters":[]},{"id":"RP-II-0115865","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115866","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아마이 조'의 민첩 판정 :\n[6] + [2] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0115867","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"오 . . .","characters":[]},{"id":"RP-II-0115868","time":"2026-07-11T17:54:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115869","time":"2026-07-11T17:55:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"아마이 조는 여기저길 누비며 나름 빠르게 서빙을 하기 시작합니다!","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115870","time":"2026-07-11T17:55:00+09:00","room":"RP II","name":"진행 / 주점 손님·호팅 포","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그 모습을 지켜보던 가게 매니저 '호팅 포' 씨는 여러분을 유심히 쳐다보고 있습니다. 메리 록... 은 진짜 여기서 일하는 점원이라 알겠는데. 점마들은 뭘까요? 뭐, 일단 일은 열심히 하는 것 같으니 두고봅시다.","characters":[]},{"id":"RP-II-0115871","time":"2026-07-11T17:55:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"옷을 갈아입고 온 메리 록! \n한층 더 편해보이는 차림입니다.\n\n\" 휴~ 그나마 좀 낫네에.\"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115872","time":"2026-07-11T17:56:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 응? 꺅! 매니저씨다아! \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115873","time":"2026-07-11T17:56:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"매, 매니저..?\"\n아마이 조는 잠시 고민했습니다.\n요즈음 돈이 부족하던 참에,\n저 사람에게 잘 보여서 일자리 하날 얻는 건 어떨까.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115874","time":"2026-07-11T17:57:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 해골 씨이~ 처음 보는 얼굴이네에. \"\n\n졸졸졸 아마이 조 뒤로 따라간다.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115875","time":"2026-07-11T17:58:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"오, 아, 안녕하세요? 전 아마이 조라고 합니다!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115876","time":"2026-07-11T17:58:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 아마이 조? 나는 메리 록이야아. 해골 씨는 어디서 왔어어? \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115877","time":"2026-07-11T17:59:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 해골과 해적.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115878","time":"2026-07-11T17:59:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"잠깐만, 그럼 메리 록 누님도 예전엔 해적이셨단 건가?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0115879","time":"2026-07-11T17:59:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 전 죽음에서 돌아온 해골입니다~~ 메리 록 씬 어디서 오셨어요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115880","time":"2026-07-11T18:04:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 후후~ 비슷한 도적이었지이. \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115881","time":"2026-07-11T18:04:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 남부 군도에서 왔어어. 죽음? 그럼... 언데드인가아? \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115882","time":"2026-07-11T18:08:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"오호, 거긴 해적들 소굴로 유명한 곳이죠? 방금 델타인 씨 말로 미뤄보면, 해적 집안이셨나봐요! 아마이징한걸요!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115883","time":"2026-07-11T18:09:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"네, 보시다시피 전 언데드죠!\"\n당당히 어깨를 피며, 엄지 손가락을 치켜세우고 자신을 가리킵니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115884","time":"2026-07-11T18:10:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 아마이징? 후후후. 재밌는 해골이구나아~ \"","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115885","time":"2026-07-11T18:12:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 감사합니다! 메리 록 씨도 되게.. 이쁘신 분이세요!\"\n말을 뱉고 나서 좀 이상한 말이었을까, 하는 생각이 들었지만 크게 신경쓰지 않기로 합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115886","time":"2026-07-11T18:15:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 정마알~? 아마이 조, 너 되게 사랑스럽다아! \"\n\n꼬오옥 안습니다!","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115887","time":"2026-07-11T18:17:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"어, 으악?!\"\n당황하며 어쩔 줄 몰라 쭈뼛거립니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115888","time":"2026-07-11T18:20:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"하지만 조는 메리 록이 원래 이런 사람인 것 같다, 라고 생각하고\n이내 어색하게 메리 록의 등을 토닥이며 당황한 티를 숨깁니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115889","time":"2026-07-11T18:30:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 그래서어, 서빙은 잘 하구 있는거야아? \"\n\n너 바라보고.","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115890","time":"2026-07-11T18:33:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"아, 아차. 헹헹헹..\"\n황급히 서빙을 다시 시작합니다.\n헐레벌떡.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115891","time":"2026-07-11T18:34:00+09:00","room":"RP II","name":"메리 록","profile":"메리 록","identity":"reviewed","type":"dialogue","body":"\" 후후후. \"\n\n매니저 몰래 다른 이들 일 시키기 란!","characters":["P-3f8ce2a4eb9b"]},{"id":"RP-II-0115892","time":"2026-07-11T18:34:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"호팅 포 옆에서 이미 쉬고 있던 델타인.","characters":["P-c93f55c91873"]},{"id":"RP-II-0115893","time":"2026-07-11T18:35:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"점점 서빙 일이 손에 익어갑니다.\n왜 이걸 하고 있었는지도 잊은 채 심취해있군요..","characters":["P-5d58655d55ce"]},{"id":"RP-II-0115894","time":"2026-07-11T19:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-II-0115895","time":"2026-07-11T19:48:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
